;------------------------------------------------------------------------------
; 4000H - ROM module header: bank 3 is called like a ROM module
; ID 43H,16H, then JP slots at +02H (reset functions), +08H (RAM-disk IOCS), +0EH
; (AUTORUN search), +15H (file handler) and the device table pointer at +11H.
;------------------------------------------------------------------------------
MODID:
	defb 43H,16H                    ; 4000  4316         module id bytes
B3RESET:
	jp B3RESETFN                    ; 4002  c3b150       module +02H: reset / power functions (A = 0..7)
L4005:
	jp MODRET                       ; 4005  c32040       module +05H: interrupt hook (unused here: JP MODRET)
B3RDSK:
	jp RDSKIOCS                     ; 4008  c39849       module +08H: RAM-disk IOCS (C = 80H..90H, A = slot)
L400B:
	jp MODRET                       ; 400B  c32040       module +0BH (unused)
B3AUTORUN:
	jp AUTORUNSRCH                  ; 400E  c36d49       module +0EH: AUTORUN.BAS search
MODDEVTAB:
	defw B3DEVTAB                   ; 4011  5349         +11H device-name table, +13H token table (none)
	defw 0000H                      ; 4013  0000
B3FILE:
	jp B3FILEHND                    ; 4015  c38c49       module +15H: file handler
	defb 10H                        ; 4018  10
L4019:
	jp MODRET                       ; 4019  c32040       module +19H (unused)
	defb 10H                        ; 401C  10
L401D:
	jp MODRET                       ; 401D  c32040       module +1DH (unused)
MODRET:
	ret                             ; 4020  c9
B3INT:
	jp B3INTHND                     ; 4021  c3de40       interrupt dispatcher (called by P0-B0 INTHND)



;------------------------------------------------------------------------------
; 4024H - Jump table 4024H-40EAH
; The P0-B0 jump-table entries named in the comments jump here with RST 18H
; (T_<name>); slots without a P0-B0 entry are used by P0-B0 internally (4048H
; NMI), by B6 (key scan, character output) or by the JAPAN ROM.
;------------------------------------------------------------------------------
T_PRTASTRO:
	jp PRTASTRO_B3                  ; 4024  c30a43       P0-B0 PRTASTRO
T_DBLMATR:
	jp DBLMATR_B3                   ; 4027  c37544       P0-B0 DBLMATR
T_ERSSTR:
	jp ERSSTR_B3                    ; 402A  c39244       P0-B0 ERSSTR
T_PRTGCHR:
	jp PRTGCHR_B3                   ; 402D  c39846       P0-B0 PRTGCHR
T_PRTGSTRO:
	jp PRTGSTRO_B3                  ; 4030  c33d43       P0-B0 PRTGSTRO
T_SAVELCD:
	jp SAVELCD_B3                   ; 4033  c35a43       P0-B0 SAVELCD
T_LOADLCD:
	jp LOADLCD_B3                   ; 4036  c3bb43       P0-B0 LOADLCD
T_PRTBSTRO:
	jp PRTBSTRO_B3                  ; 4039  c31044       P0-B0 PRTBSTRO
T_KBUFSET:
	jp KBUFSET_B3                   ; 403C  c3fa46       P0-B0 KBUFSET
T_CALLH:
	jp CALLH_B3                     ; 403F  c3ce5b       P0-B0 CALLH
T_PWROFF:
	jp PWROFF_B3                    ; 4042  c3ec5c       P0-B0 PWROFF
T_INT150:
	jp INT150_B3                    ; 4045  c3c15c       P0-B0 INT150
T_NMI150:
	jp NMI150                       ; 4048  c3475d
T_USCNVL:
	jp USCNVL_B3                    ; 404B  c3305d       P0-B0 USCNVL
T_PUTCHR:
